<?php
declare(strict_types=1);
$scopeProfile='contribuyentes/perfil&id='.$tabsId.'&anio=2025';
$scopeComponent='planeacion/datos&id='.$tabsId.'&anio=2025';
[$s,$html]=request($client,$base,$scopeProfile.'&tab=personal');
verify($s===200 && str_contains($html,'campo-tipo_pension') && !str_contains($html,'name="campos[eps]"'),'Perfil personal no pide afiliaciones ni planillas');
verify(str_contains($html,'Complemento personal, no casilla del RUT') && str_contains($html,'class="profile-help"'),'La ayuda explica finalidad y origen de los complementos');
[$s,$html]=request($client,$base,$scopeComponent.'&tab=seguridad');
verify($s===200 && str_contains($html,'name="campos[eps]"') && !str_contains($html,'name="campos[tipo_pension]"'),'Seguridad social recibe los datos trasladados sin duplicar condición pensional');
$scopePost=['_csrf_token'=>token($html),'revision'=>'0','estado'=>'borrador','campos'=>['eps'=>'EPS ficticia','pila'=>'si']];
verify(request($client,$base,$scopeComponent.'&tab=seguridad',$scopePost)[0]===303,'Guarda afiliación en el componente correspondiente');
$scopePost['revision']='1';$scopePost['campos']=['tipo_pension'=>'vejez','eps'=>'Intento fuera de alcance'];
verify(request($client,$base,$scopeProfile.'&tab=personal',$scopePost)[0]===303,'Guarda condición pensional desde el perfil');
$tabsQuery->execute([$tabsId,'seguridad']);$scopeData=json_decode($tabsQuery->fetch()['datos'],true);
verify($scopeData['campos']['eps']==='EPS ficticia' && $scopeData['campos']['tipo_pension']==='vejez' && $scopeData['campos']['pila']==='si','Guardar perfil conserva los datos trasladados e ignora campos fuera de alcance');
[$s,$html]=request($client,$base,$scopeComponent.'&tab=dependientes');
$tabsQuery->execute([$tabsId,'relacionados']);$scopeRevision=$tabsQuery->fetch()['revision'];
$scopePerson=['rol'=>'dependiente','nombre'=>'Familiar de prueba','documento_tipo'=>'CC','documento'=>'123456','parentesco'=>'Hijo','dependencia'=>'Certificado ficticio','reclamado'=>'no'];
$scopePost=['_csrf_token'=>token($html),'revision'=>(string)$scopeRevision,'estado'=>'borrador','aplicabilidad'=>'si','filas'=>[$scopePerson]];
verify(request($client,$base,$scopeComponent.'&tab=dependientes',$scopePost)[0]===303,'Registra las condiciones del beneficio por dependiente fuera del perfil');
[$s,$html]=request($client,$base,$scopeProfile.'&tab=familia');
verify(str_contains($html,'Familiar de prueba') && !str_contains($html,'[dependencia]') && !str_contains($html,'[reclamado]'),'El perfil muestra la identidad familiar y retira las preguntas de beneficios');
$tabsQuery->execute([$tabsId,'relacionados']);$scopeSaved=$tabsQuery->fetch();
$scopePerson['_origen']='0';$scopePerson['nombre']='Familiar actualizado';unset($scopePerson['dependencia'],$scopePerson['reclamado']);
$scopePost=['_csrf_token'=>token($html),'revision'=>(string)$scopeSaved['revision'],'estado'=>'borrador','aplicabilidad'=>'si','filas'=>[$scopePerson]];
verify(request($client,$base,$scopeProfile.'&tab=familia',$scopePost)[0]===303,'Permite actualizar la identidad del familiar en el perfil');
$tabsQuery->execute([$tabsId,'relacionados']);$scopeRows=json_decode($tabsQuery->fetch()['datos'],true)['filas'];
$scopeDependent=array_values(array_filter($scopeRows,static fn($r)=>$r['rol']==='dependiente'))[0];
verify(count($scopeRows)===4 && $scopeDependent['dependencia']==='Certificado ficticio' && $scopeDependent['reclamado']==='no','Conserva soporte de beneficio, socios, contador y representación al editar al familiar');
verify(request($client,$base,$scopeProfile.'&tab=familia',$scopePost)[0]===409,'Los dos componentes comparten control de revisión y rechazan una edición antigua');
verify(request($client,$base,'planeacion/datos&id='.$otherId.'&tab=seguridad')[0]===404,'Los componentes trasladados mantienen privacidad por contribuyente');
[$s,$html]=request($client,$base,$scopeProfile.'&tab=fiscal');
verify(!str_contains($html,'name="campos[obligacion_renta]"') && str_contains($html,'name="campos[residencia]"'),'El perfil distingue residencia de la revisión anual de declaración');
